{
  "narrative_summary": "This result rests on the link from Engineering Capacity to Total Cost of Ownership, which is not yet well evidenced. If capacity assumptions change, more runs could support a different option. In this model, 58% of runs supported Rebuild In House.",
  "story_headlines": {
    "opt_rebuild": "Rebuild In House gains when engineering capacity holds up as modelled, lowering total cost of ownership.",
    "opt_extend": "Extend Vendor Contract gains more runs if vendor price path stays flatter than currently modelled."
  },
  "robustness_explanation": {
    "summary": "The ordering holds in about 61% of variations, based on current estimates given the low overall confidence behind this comparison.",
    "primary_risk": "The link from Engineering Capacity to Total Cost of Ownership is not well evidenced and could shift the comparison.",
    "stability_factors": [],
    "fragility_factors": [
      "The link from Engineering Capacity to Total Cost of Ownership is the main source of fragility in this result."
    ]
  },
  "readiness_rationale": "Two gaps still hold this back: engineering capacity is asserted rather than evidenced, and confidence behind both factors remains low. More evidence would settle this further.",
  "evidence_enhancements": {
    "fac_eng_capacity": {
      "specific_action": "Run a capacity audit against current engineering headcount and planned commitments to test the assumption directly.",
      "rationale": "This factor carries the most value-of-information in this comparison and is currently asserted rather than evidenced.",
      "evidence_type": "internal_data",
      "decision_hygiene": "Estimate available capacity before looking at the audit results."
    },
    "fac_vendor_price": {
      "specific_action": "Request the vendor's multi-year price schedule or escalation clause in writing before renewal talks.",
      "rationale": "Vendor Price Path has moderate confidence and directly affects total cost of ownership.",
      "evidence_type": "market_research",
      "decision_hygiene": "Write down your expected price trajectory before requesting the schedule."
    }
  },
  "scenario_contexts": {
    "edge_capacity_tco": {
      "trigger_description": "If Engineering Capacity falls short of what the link to Total Cost of Ownership currently assumes...",
      "consequence": "...then the most runs would support Extend Vendor Contract rather than Rebuild In House."
    }
  },
  "flip_thresholds": [],
