    {
      "type": "DOMINANT_FACTOR",
      "source": "structural",
      "description": "Engineering capacity is asserted rather than evidenced, yet it anchors much of this comparison. Is that concentration intentional?",
      "affected_elements": ["fac_eng_capacity", "edge_capacity_tco"],
      "suggested_action": "Evidence the engineering capacity assumption before treating this comparison as settled.",
      "linked_critique_code": "unsupported_link"
    }
  ],
  "key_assumptions": [
    "The link from Engineering Capacity to Total Cost of Ownership assumes current team throughput continues without disruption.",
    "The link from Vendor Price Path to Total Cost of Ownership assumes pricing trends continue as currently modelled.",
    "The brief frames this as a build-versus-extend choice without naming a specific cost or timeline target."
  ],
  "decision_quality_prompts": [
    {
      "question": "What is the base rate for efforts like Rebuild In House succeeding on the timelines typically assumed?",
      "principle": "Outside View (Kahneman)",
      "applies_because": "Overall confidence in this comparison is low, and an outside view would test whether the modelled assumptions are realistic."
    },
    {
      "question": "Who will argue that Engineering Capacity matters less than Vendor Price Path in this decision?",
      "principle": "Structured dissent",
      "applies_because": "One factor is asserted rather than evidenced and anchors much of the comparison, so structured dissent would test that concentration."
    }
  ],
  "pre_mortem": {
    "failure_scenario": "Six months on, Rebuild In House failed because Engineering Capacity fell short of what was assumed, driving Total Cost of Ownership above plan.",
